const fs = require('fs');
const path = require('path');

// ============================================
// Configuratie — pas dit pad aan!
// ============================================
const BASE_DIR = '/home/user/n8n-files/projects';

const input = $input.first();
const body = input.json.body || input.json;
const projectId = String(body.project_id || '').replace(/[^a-zA-Z0-9_-]/g, '');
const subPath = String(body.path || '').replace(/\.\./g, '').replace(/[^a-zA-Z0-9/_.-]/g, '_');

if (!projectId || !subPath) {
  throw new Error('project_id en path zijn verplicht.');
}

const targetDir = path.join(BASE_DIR, projectId, subPath);

// Maak directory aan als die niet bestaat
fs.mkdirSync(targetDir, { recursive: true });

// Verwerk binaire bestanden
const binaryKeys = Object.keys(input.binary || {});
const savedFiles = [];

for (const key of binaryKeys) {
  const binaryData = input.binary[key];
  const fileName = binaryData.fileName || `upload_${Date.now()}.jpg`;
  const safeName = fileName.replace(/[^a-zA-Z0-9._-]/g, '_');
  const filePath = path.join(targetDir, safeName);

  // Haal binary data op via n8n helper
  const buffer = await this.helpers.getBinaryDataBuffer(0, key);
  fs.writeFileSync(filePath, buffer);
  savedFiles.push({ name: safeName, path: filePath });
}

return [{
  json: {
    success: true,
    message: `${savedFiles.length} bestand(en) opgeslagen.`,
    files: savedFiles.map(f => f.name)
  }
}];
